  id String @id @db.Uuid

  /// The user who requested the password reset. {@link todo_app_users.id}.
  todo_app_user_id String @db.Uuid

  /// Unique token generated for the password reset process. Used to
  /// authenticate the reset attempt.
  token String

  /// Expiration date and time of the password reset token. After this, the
  /// token becomes invalid.
  expires_at DateTime @db.Timestamptz

  /// Timestamp when the password reset request was initiated.
  requested_at DateTime @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

