import { ArrayUtil, RandomGenerator } from "@nestia/e2e";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ITodoAppRefreshToken } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppRefreshToken";
export function prepare_random_todo_app_refresh_token(
  input?: DeepPartial<ITodoAppRefreshToken.ICreate>,
): ITodoAppRefreshToken.ICreate {
  return {
    refresh_token: input?.refresh_token ?? RandomGenerator.alphaNumeric(64),
    user_id:
      input?.user_id !== undefined
        ? input.user_id
        : typia.random<boolean>()
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
    user_session_id:
      input?.user_session_id !== undefined
        ? input.user_session_id
        : typia.random<boolean>()
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
    expired_at:
      input?.expired_at ??
      RandomGenerator.date(new Date(), 1000 * 60 * 60 * 24 * 30).toISOString(),
  };
}

import { ArrayUtil, RandomGenerator } from "@nestia/e2e";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ITodoAppConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppConfiguration";
export function prepare_random_todo_app_configuration(
  input?: DeepPartial<ITodoAppConfiguration.ICreate>,
): ITodoAppConfiguration.ICreate {
  return {
    key:
      input?.key ??
      RandomGenerator.alphabets(
        typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<5> & tags.Maximum<15>
        >(),
      ),
    value:
      input?.value ??
      RandomGenerator.paragraph({
        sentences: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<3>
        >(),
      }),
    description:
      input?.description !== undefined
        ? input.description === null
          ? null
          : input.description
        : RandomGenerator.paragraph({
            sentences: typia.random<
              number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<2>
            >(),
          }),
    type:
      input?.type ??
      RandomGenerator.pick(["boolean", "string", "number"] as const),
  };
}

import { ArrayUtil, RandomGenerator } from "@nestia/e2e";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ITodoAppAccessToken } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAccessToken";
export function prepare_random_todo_app_access_token(
  input?: DeepPartial<ITodoAppAccessToken.ICreate>,
): ITodoAppAccessToken.ICreate {
  return {
    token: input?.token ?? RandomGenerator.alphaNumeric(40),
    type: input?.type ?? "bearer",
    issued_at:
      input?.issued_at ?? new Date(Date.now() - 1000 * 60 * 60).toISOString(),
    expired_at:
      input?.expired_at ??
      new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
    revoked_at:
      input?.revoked_at === undefined
        ? RandomGenerator.pick([
            null,
            new Date(Date.now() - 1000 * 60 * 10).toISOString(),
          ])
        : input.revoked_at,
    todo_app_user_id:
      input?.todo_app_user_id === undefined
        ? RandomGenerator.pick([
            null,
            typia.random<string & tags.Format<"uuid">>(),
          ])
        : input.todo_app_user_id,
    todo_app_guest_id:
      input?.todo_app_guest_id === undefined
        ? RandomGenerator.pick([
            null,
            typia.random<string & tags.Format<"uuid">>(),
          ])
        : input.todo_app_guest_id,
    todo_app_user_session_id:
      input?.todo_app_user_session_id === undefined
        ? RandomGenerator.pick([
            null,
            typia.random<string & tags.Format<"uuid">>(),
          ])
        : input.todo_app_user_session_id,
  };
}

