                        ? null
                        : accessToken.todo_app_user_id === undefined
                          ? undefined
                          : accessToken.todo_app_user_id,
                    todo_app_guest_id:
                      accessToken.todo_app_guest_id === null
                        ? null
                        : accessToken.todo_app_guest_id === undefined
                          ? undefined
                          : accessToken.todo_app_guest_id,
                    todo_app_user_session_id:
