export async function postAuthUserLogin(props: {
  body: ITodoAppUser.ILogin;
}): Promise<ITodoAppUser.IAuthorized> {
  const user = await MyGlobal.prisma.todo_app_users.findFirst({
    where: { email: props.body.email },
    select: {
      id: true,
      email: true,
      username: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      password_hash: true,
      accessTokens: {
        select: {
          id: true,
          created_at: true,
          updated_at: true,
          expired_at: true,
          todo_app_guest_id: true,
          todo_app_user_session_id: true,
          token: true,
          type: true,
          issued_at: true,
          revoked_at: true,
        },
      },
      refreshTokens: {
        select: {
          id: true,
          created_at: true,
          token_expired_at: true,
          verified_at: true,
          deleted_at: true,
          token: true,
        },
      },
      emailVerifications: {
        select: {
          id: true,
          created_at: true,
          deleted_at: true,
          token: true,
          token_expired_at: true,
          verified_at: true,
        },
      },
      userPasswordResets: {
        select: {
          id: true,
          created_at: true,
          deleted_at: true,
          token: true,
          expires_at: true,
          requested_at: true,
          updated_at: true,
        },
      },
      userRoles: {
        select: {
          id: true,
          created_at: true,
          status: true,
          updated_at: true,
        },
      },
      sessions: {
        select: {
          id: true,
          created_at: true,
          ip: true,
          href: true,
          referrer: true,
          expired_at: true,
        },
      },
      todoItems: {
        select: {
          id: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          description: true,
          title: true,
          status: true,
        },
      },
      auditLogs: {
        select: {
          id: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          todo_app_todo_item_id: true,
          action: true,
        },
      },
    },
  });
  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const now = toISOStringSafe(new Date());
  const session = await MyGlobal.prisma.todo_app_user_sessions.create({
    data: {
      id: v4(),
      todo_app_user_id: user.id,
